begin;
create schema domain_reserve_test;
create function domain_reserve_test.ok(condition boolean,message text) returns void language plpgsql as $$ begin if not coalesce(condition,false) then raise exception 'DOMAIN RESERVE ASSERTION FAILED: %',message; end if;raise notice 'ok - domain reserve: %',message;end; $$;
create function domain_reserve_test.fails(statement text,message text) returns void language plpgsql as $$ begin begin execute statement; exception when others then raise notice 'ok - domain reserve: % (refused)',message;return;end;raise exception 'DOMAIN RESERVE ASSERTION FAILED: %',message;end; $$;
grant usage on schema domain_reserve_test to anon,authenticated,service_role;
grant execute on all functions in schema domain_reserve_test to anon,authenticated,service_role;
insert into auth.users(id,email) values('ac100000-0000-0000-0000-000000000001','reserve-owner@example.test');
insert into public.organizations(id,name,slug) values('ac200000-0000-0000-0000-000000000001','Reserve tests','domain-reserve-tests');
insert into public.organization_members(organization_id,user_id,role) values('ac200000-0000-0000-0000-000000000001','ac100000-0000-0000-0000-000000000001','owner');
insert into public.websites(id,organization_id,name) values('ac300000-0000-0000-0000-000000000001','ac200000-0000-0000-0000-000000000001','Reserve website');
insert into vigil.domain_launch_profiles(id,registrar_scope,stripe_account,max_registrar_minor,max_client_minor,service_fee_minor,allowed_country,terms_version,terms_url,registration_agreement_url,renewal_policy_version,retention_days,purchasing_enabled,tax_code,fee_tax_code,tax_review_reference,supplier_tax_reference,approval_reference,approved_by,valid_until,allowed_regions,reserve_service_fee,supplier_tax_allowance_minor)
 values('ac400000-0000-0000-0000-000000000001','namecom:live:'||repeat('a',64),'acct_fixture',2000,3000,500,'US','domain-v1','https://example.test/terms','https://www.name.com/policies/registration-agreement','manual-v1',2557,true,'txcd_20030000','txcd_20030000','fixture NY review','fixture bounded supplier review','fixture approval only','ac100000-0000-0000-0000-000000000001',now()+interval '1 day',array['NY'],true,500);
select set_config('request.jwt.claims','{"role":"authenticated","sub":"ac100000-0000-0000-0000-000000000001"}',true);
set local role authenticated;
select domain_reserve_test.fails('select * from vigil.domain_order_financials','customer cannot inspect any reserve ledger');
select domain_reserve_test.fails('select public.domain_financial_summary()','customer cannot inspect financial summary');
select domain_reserve_test.fails('select vigil.record_live_domain_registration_base(null,null,null,null)','original registration helper cannot bypass receipt validation');
reset role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
set local role service_role;
do $$
declare p jsonb;q uuid;final_q uuid;o uuid;asset uuid;d jsonb;scope text:='namecom:live:'||repeat('a',64);
begin
 p:=public.ensure_domain_website_policy('ac200000-0000-0000-0000-000000000001','ac300000-0000-0000-0000-000000000001','ac100000-0000-0000-0000-000000000001','ac400000-0000-0000-0000-000000000001');
 perform domain_reserve_test.ok(p->'allowed_regions'='["NY"]'::jsonb and (p->>'reserve_service_fee')::boolean,'website policy retains scoped release and reserve rules');
 q:=public.create_live_domain_quote('ac200000-0000-0000-0000-000000000001','ac300000-0000-0000-0000-000000000001','reserve-fixture.com',1200,1400,now()+interval '5 minutes');
 perform domain_reserve_test.fails(format('select public.create_taxed_domain_quote(%L,%L,%L,''taxcalc_wrong'',%L,0,1700,now()+interval ''1 hour'',''acct_fixture'',''[]'',''WA'')',q,'ac200000-0000-0000-0000-000000000001','ac100000-0000-0000-0000-000000000001',repeat('a',64)),'unreviewed state refused by SQL before checkout');
 perform domain_reserve_test.fails(format('select public.create_taxed_domain_quote(%L,%L,%L,''taxcalc_missing'',%L,0,1700,now()+interval ''1 hour'',''acct_fixture'',''[]'')',q,'ac200000-0000-0000-0000-000000000001','ac100000-0000-0000-0000-000000000001',repeat('a',64)),'omitting jurisdiction cannot bypass restricted release');
 final_q:=public.create_taxed_domain_quote(q,'ac200000-0000-0000-0000-000000000001','ac100000-0000-0000-0000-000000000001','taxcalc_reserve',repeat('a',64),0,1700,now()+interval '1 hour','acct_fixture','[]','NY');
 o:=public.create_domain_purchase(final_q,'ac200000-0000-0000-0000-000000000001','ac100000-0000-0000-0000-000000000001',gen_random_uuid(),gen_random_uuid(),repeat('x',100),repeat('a',64),1700,'usd',false,'domain-v1','manual-v1');
 perform domain_reserve_test.ok((public.domain_engine_order_context(o)->>'maximum_registrar_total_minor')::bigint=1700,'supplier allowance is derived privately from original policy');
 update public.domain_orders set registration_state='submitting',payment_state='authorized' where id=o;
 d:=jsonb_build_object('fqdn','reserve-fixture.com','status','registered','contactVerification','pending','expiresAt',now()+interval '1 year','autoRenew',false,'supplierReceipt',jsonb_build_object('baseMinor',1200,'taxMinor',120,'totalMinor',1320));
 perform domain_reserve_test.fails(format('select public.record_live_domain_registration(%L,%L,%L,%L)',o,d,scope||':domain:reserve-fixture.com',scope),'missing original supplier order cannot create ledger or asset');
 insert into public.provider_links(provider,resource_kind,external_id,entity_type,entity_id,metadata) values('other','registrar_order',scope||':order:123','domain_order',o,jsonb_build_object('environment','live','account_scope',scope));
 perform domain_reserve_test.fails(format('select public.record_live_domain_registration(%L,%L,%L,%L)',o,d-'supplierReceipt',scope||':domain:reserve-fixture.com',scope),'missing receipt cannot create a reserved registration');
 perform domain_reserve_test.fails(format('select public.record_live_domain_registration(%L,%L,%L,%L)',o,jsonb_set(d,'{supplierReceipt}',jsonb_build_object('baseMinor',1200,'taxMinor',900,'totalMinor',2100)),scope||':domain:reserve-fixture.com',scope),'over-budget supplier total refused atomically');
 perform domain_reserve_test.ok((select count(*)=0 from vigil.domain_order_financials),'rejected evidence leaves no partial ledger');
 asset:=public.record_live_domain_registration(o,d,scope||':domain:reserve-fixture.com',scope);
 perform domain_reserve_test.ok(asset=public.record_live_domain_registration(o,d,scope||':domain:reserve-fixture.com',scope),'duplicate provider reconciliation preserves same registration');
 perform domain_reserve_test.ok((select count(*)=1 from vigil.domain_order_financials),'duplicate receipt creates one ledger row');
 perform domain_reserve_test.ok((select reserve_minor=500 and reserve_state='pending' and supplier_total_minor=1320 and supplier_tax_minor=120 from vigil.domain_order_financials where order_id=o),'supplier tax and full fee reserve are separately persisted');
 perform domain_reserve_test.ok((public.domain_financial_summary()->>'heldMinor')::bigint=0,'authorization does not pretend cash is collected');
 update public.domain_orders set payment_state='paid' where id=o;
 perform domain_reserve_test.ok((public.domain_financial_summary()->>'heldMinor')::bigint=500,'confirmed payment holds the entire fee');
 perform domain_reserve_test.ok((select total_minor=1700 and tax_minor=0 from public.domain_quotes where id=final_q),'supplier tax does not increase customer total or customer tax');
 perform domain_reserve_test.fails(format('select public.record_live_domain_registration(%L,%L,%L,%L)',o,jsonb_set(d,'{supplierReceipt,taxMinor}','100'),scope||':domain:reserve-fixture.com',scope),'receipt evidence cannot be replaced');
 perform domain_reserve_test.fails(format('update vigil.domain_order_financials set reserve_minor=0 where order_id=%L',o),'service role cannot silently clear reserve');
 update public.domain_orders set payment_state='refunded' where id=o;
 perform domain_reserve_test.ok((public.domain_financial_summary()->>'heldMinor')::bigint=0 and (select reserve_state='refunded' and reserve_minor=500 from vigil.domain_order_financials where order_id=o),'full refund stops counting held cash and preserves original reserve evidence');
end; $$;
reset role;
rollback;
